use gt4l_disc::{identify, setup, spec2, DiscGame, Pins, SetupRequest, Spec2Pins, Stage};
use std::{env, path::PathBuf, process::ExitCode, sync::atomic::AtomicBool};

fn main() -> ExitCode {
    let args: Vec<_> = env::args_os().skip(1).collect();
    if args.len() != 2 {
        eprintln!("usage: getall-gt4-disc <original.iso> <staged-port-root>");
        return ExitCode::from(2);
    }
    match prepare(PathBuf::from(&args[0]), PathBuf::from(&args[1])) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("{error}");
            ExitCode::FAILURE
        }
    }
}

fn prepare(disc: PathBuf, root: PathBuf) -> Result<(), String> {
    if !root.is_absolute() || !root.is_dir() || !disc.is_absolute() {
        return Err("Both paths must be absolute and the staged port folder must exist.".into());
    }
    let gt4 = Pins::embedded()?;
    let spec = Spec2Pins::embedded()?;
    let game = identify::identify(&disc, &gt4, &spec)
        .map_err(|e| e.user_message())?
        .game;
    let game_data = root.join("data").join("games").join(game.id());
    let prepared = game_data.join("prepared");
    let staging = game_data.join("prepared.tmp");
    let disc_dir = game_data.join("disc");
    if prepared.exists() || staging.exists() {
        return Err("Expected a fresh staged port.".into());
    }
    let cancel = AtomicBool::new(false);
    let mut last = None;
    let mut report = |stage: Stage, fraction: f32| {
        let percent = (fraction.clamp(0.0, 1.0) * 100.0) as u8;
        let key = (format!("{stage:?}"), percent);
        if last.as_ref() != Some(&key) {
            println!("{} {}", key.0, key.1);
            last = Some(key);
        }
    };
    let status = match game {
        DiscGame::Gt4 => {
            setup::run(
                &SetupRequest {
                    disc: &disc,
                    prepared: &prepared,
                    staging: &staging,
                    install_dir: &root,
                    pins: &gt4,
                    launcher_version: "1.3.0-rc16",
                    cancel: &cancel,
                },
                &mut report,
            )
            .map_err(|e| e.user_message())?;
            setup::check_installed(&prepared, &disc_dir, &root, &gt4)
        }
        DiscGame::Spec2 => {
            spec2::run(
                &spec2::Spec2Request {
                    disc: &disc,
                    prepared: &prepared,
                    staging: &staging,
                    install_dir: &root,
                    pins: &spec,
                    launcher_version: "1.3.0-rc16",
                    cancel: &cancel,
                },
                &mut report,
            )
            .map_err(|e| e.user_message())?;
            spec2::check_installed(&prepared, &disc_dir, &root, &spec)
        }
    };
    if !matches!(status, setup::Installed::Ready { .. }) {
        return Err("The official setup did not produce a ready installation.".into());
    }
    println!("READY {}", game.id());
    Ok(())
}
